import re

def parse(lines):
    err_re = re.compile(r'^jq: error(?: \(at (?P<location>[^)]*)\))?: (?P<message>.*)$')
    hdr_re = re.compile(r'^(?P<ind>\s*)(?P<name>[^\s\[][^\s]*):$')
    par_re = re.compile(r'^\s*\[params: (?P<params>.*)\]$')
    ins_re = re.compile(r'^(?P<ind>\s*)(?P<offset>\d{4}) (?P<opcode>[A-Z_][A-Z0-9_]*)(?: (?P<operand>.*\S))?\s*$')
    errors = []
    err_lines = []
    funcs = []
    func_lines = []
    fidx = {}
    ins = []
    ins_lines = []
    stack = []
    for i, line in enumerate(lines):
        if not line.strip():
            continue
        m = err_re.match(line)
        if m:
            errors.append({'location': m.group('location') or '', 'message': m.group('message')})
            err_lines.append(i)
            continue
        m = ins_re.match(line)
        if m:
            ind = len(m.group('ind'))
            while stack and stack[-1][0] >= ind:
                stack.pop()
            fn = '/'.join(s[1] for s in stack) or 'main'
            ins.append({'function': fn, 'offset': m.group('offset'), 'opcode': m.group('opcode'), 'operand': m.group('operand') or ''})
            ins_lines.append(i)
            continue
        m = par_re.match(line)
        if m:
            if stack:
                fn = '/'.join(s[1] for s in stack)
                if fn in fidx:
                    funcs[fidx[fn]]['params'] = m.group('params')
                    func_lines.append(i)
                    continue
            continue
        m = hdr_re.match(line)
        if m:
            ind = len(m.group('ind'))
            while stack and stack[-1][0] >= ind:
                stack.pop()
            stack.append((ind, m.group('name')))
            fn = '/'.join(s[1] for s in stack)
            fidx[fn] = len(funcs)
            funcs.append({'function': fn, 'params': ''})
            func_lines.append(i)
            continue
    blocks = []
    if errors:
        blocks.append({'name': 'errors', 'kind': 'table', 'lines': err_lines, 'records': errors})
    if funcs:
        blocks.append({'name': 'functions', 'kind': 'table', 'lines': sorted(func_lines), 'records': funcs})
    if ins:
        blocks.append({'name': 'instructions', 'kind': 'table', 'lines': ins_lines, 'records': ins})
    return {'blocks': blocks, 'skip': []}
